            RegistryChildListenerImpl that = (RegistryChildListenerImpl) o;
            return Objects.equals(serviceName, that.serviceName)
                    && Objects.equals(consumerUrl, that.consumerUrl)
                    && Objects.equals(listener, that.listener);
